  {
    family: "unturned",
    name: "Unturned Server",
    minRamMB: 2048,
    minDiskGB: 10,
    // Replaces the wave2 draft's "fragsoc/unturned" — that image was never actually
    // published (Docker Hub/GHCR 404; its repo ships only a Dockerfile to build
    // yourself). imperialplugins/unturned is a real, published, actively-pulled image.
    //
    // The image BAKES the whole game into /home/steam/Unturned (the binary and all
    // Bundles/Content ship in the image; init.sh only runs it, it does not download).
    // The mutable server data — worlds, config, players — lives under that dir's
    // Servers/ subfolder. So we bind-mount ONLY /home/steam/Unturned/Servers, not the
    // whole game dir: mounting an empty host dir over /home/steam/Unturned shadowed
    // the baked-in binary and the container crash-looped forever on
    // "./Unturned_Headless.x86_64: No such file or directory" (exit 127) — every
    // Unturned order was 100% dead (verified live 2026-09-07). The image runs as
    // uid 1000 (steam), so pre-chown the host dir or it cannot write the server data.
    setupScript:
      `curl -fsSL https://get.docker.com | sh && mkdir -p /opt/unturned && chown -R 1000:1000 /opt/unturned && docker run -d --name unturned -p 27015:27015/tcp -p 27015:27015/udp -p 27016:27016/udp -v /opt/unturned:/home/steam/Unturned/Servers -e GAME_ID=1110390 -e SERVER_NAME='Nxeon Unturned' -e SERVER_TYPE=vanilla --restart unless-stopped imperialplugins/unturned:latest`,
  },
  {
    family: "theforest",
    name: "The Forest Server",
    minRamMB: 4096,
    minDiskGB: 20,
    setupScript:
      `curl -fsSL https://get.docker.com | sh && mkdir -p /opt/theforest && docker run -d --name theforest -p 27015-27016:27015-27016/udp -p 8766:8766/udp -v /opt/theforest:/theforest -e PUID=1000 -e PGID=1000 -e ALWAYS_UPDATE_ON_START=true -e FILTER_SHADER_AND_MESH_AND_WINE_DEBUG=true --restart unless-stopped jammsen/the-forest-dedicated-server:latest`,
  },
  {
    family: "sonsoftheforest",
    name: "Sons of the Forest Server",
    minRamMB: 4096,
    minDiskGB: 25,
    setupScript:
      `curl -fsSL https://get.docker.com | sh && mkdir -p /opt/sonsoftheforest && docker run -d --name sonsoftheforest -p 8766:8766/udp -p 27016:27016/udp -p 9700:9700/udp -v /opt/sonsoftheforest:/sonsoftheforest -e PUID=1000 -e PGID=1000 -e ALWAYS_UPDATE_ON_START=true -e SKIP_NETWORK_ACCESSIBILITY_TEST=true -e FILTER_SHADER_AND_MESH_AND_WINE_DEBUG=true --restart unless-stopped jammsen/sons-of-the-forest-dedicated-server:latest`,
  },
  {
    family: "bedrock",
    name: "Minecraft Bedrock Server",
    minRamMB: 1024,
    minDiskGB: 5,
    setupScript:
      `curl -fsSL https://get.docker.com | sh && docker run -d --name bedrock -e EULA=TRUE -e SERVER_NAME="Nxeon Bedrock Server" -e GAMEMODE=survival -e DIFFICULTY=normal -e LEVEL_NAME=Bedrock -e MAX_PLAYERS=10 -e ALLOW_CHEATS=false -e VERSION=LATEST -p 19132:19132/udp -v /opt/bedrock:/data --restart unless-stopped itzg/minecraft-bedrock-server`,
  },
];

